INSERT INTO items(asset_id,name,category,command,page_url,icon_path,description) VALUES ('BakedMeat_BerryGoat','Herb Roasted Caprity','Food','!giveme BakedMeat_BerryGoat:9999','https://paldeck.cc/items/BakedMeat_BerryGoat','Icons/BakedMeat_BerryGoat.webp','Mild roast filled with the natural aromas of herbs and berries embedded in the meat. Gives a pleasant sense of warmth when eaten outdoors.');
INSERT INTO items(asset_id,name,category,command,page_url,icon_path,description) VALUES ('BakedMeat_Boar','Roast Rushoar','Food','!giveme BakedMeat_Boar:9999','https://paldeck.cc/items/BakedMeat_Boar','Icons/BakedMeat_Boar.webp','Boar grilled over a hearty flame. Crispy on the outside, juicy on the inside. Perfect as an extravagant main dish for a big party.');
INSERT INTO items(asset_id,name,category,command,page_url,icon_path,description) VALUES ('BakedMeat_CowPal','Mozzarina Steak','Food','!giveme BakedMeat_CowPal:9999','https://paldeck.cc/items/BakedMeat_CowPal','Icons/BakedMeat_CowPal.webp','Thick, well-done steak. Strong flavors give those who eat it an energy boost.');
INSERT INTO items(asset_id,name,category,command,page_url,icon_path,description) VALUES ('BakedMeat_Deer','Roast Eikthyrdeer','Food','!giveme BakedMeat_Deer:9999','https://paldeck.cc/items/BakedMeat_Deer','Icons/BakedMeat_Deer.webp','Carefully roasted venison with delicate flavor notes, accented by the aromas of the deep forest. Elegant taste for an elegant lifestyle.');
