INSERT INTO items(asset_id,name,category,command,page_url,icon_path,description) VALUES ('BakedMeat_IceCrocodile','Munchill Steak','Food','!giveme BakedMeat_IceCrocodile:9999','https://paldeck.cc/items/BakedMeat_IceCrocodile','Icons/BakedMeat_IceCrocodile.webp','Charcoal-grilled to perfection, this steak offers a crispy exterior and melt-in-your-mouth juiciness. Unique compounds seal in flavor and enhance shelf life.');
INSERT INTO items(asset_id,name,category,command,page_url,icon_path,description) VALUES ('BakedMeat_IceDeer','Roast Reindrix','Food','!giveme BakedMeat_IceDeer:9999','https://paldeck.cc/items/BakedMeat_IceDeer','Icons/BakedMeat_IceDeer.webp','When taken from a flame, Reindrix meat rapidly drops in temperature. This allows it to retain freshness for long periods of time, making it a perfect emergency ration.');
