INSERT INTO items(asset_id,name,category,command,page_url,icon_path,description) VALUES ('QuestItem_Farmer_1','Farmer''s Special Dish','Other','!giveme QuestItem_Farmer_1:9999','https://paldeck.cc/items/QuestItem_Farmer_1','Icons/QuestItem_Farmer_1.webp','A home-cooked meal from a doting farmer. It gives off an absolutely mouthwatering aroma.');
INSERT INTO items(asset_id,name,category,command,page_url,icon_path,description) VALUES ('QuestItem_Zoe_1','Zoe''s Tattered Memento','Other','!giveme QuestItem_Zoe_1:9999','https://paldeck.cc/items/QuestItem_Zoe_1','Icons/QuestItem_Zoe_1.webp','A worn scrap of fabric with a faint lingering scent. To Zoe, it''s a treasured reminder of the past.');
INSERT INTO items(asset_id,name,category,command,page_url,icon_path,description) VALUES ('QuestItem_Zoe_Halloweenskin_1','Zoe''s Halloween Costume','Other','!giveme QuestItem_Zoe_Halloweenskin_1:9999','https://paldeck.cc/items/QuestItem_Zoe_Halloweenskin_1','Icons/QuestItem_Zoe_Halloweenskin_1.webp','A Halloween outfit for Zoe. She''s bound to love it, so let''s give it to her!');
INSERT INTO items(asset_id,name,category,command,page_url,icon_path,description) VALUES ('Quiche','Mushroom Quiche','Food','!giveme Quiche:9999','https://paldeck.cc/items/Quiche','Icons/Quiche.webp','A dish made by baking a pastry crust filled with eggs, vegetables, mushrooms, and cream. It’s delicious even when cooled. Eating it will help you stay fuller for a while and make it harder for your SAN value to decrease for a period of time.');
